#!/bin/bash
# land-daylight-observatory.sh — astrology's third sky: the daylight
# observatory on the city's own white. The hub RETURNS its ground grant
# (relief.spec's granted list is four for the first time since the night
# shipped), the velvet's pane rules are deleted rather than restyled, the
# header/rail/chips go frosted milk glass, and two soft greys get a scoped
# handoff measured against the whisper's densest blend.
#
# FRONTEND ONLY (together-city-react). Push, and Vercel ships it.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="A timestamp is not a face"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-timestamp-face.sh first."; exit 1 ;;
esac
NEEDS="The observatory opens its curtains"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/daylight.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="8b81fe5bfe46f1b9a27d1bbbf796b88dff642ff83d58e41afafae5bcf6e4c40c"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS — push and Vercel ships it."
echo " Astrology now stands in daylight: white ground, frosted rail,"
echo " deepened gold. Its ground grant is returned; the spec's list"
echo " of grounded hubs is four."
echo "==============================================================="
